using System;
using System.IO;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
using UnityEngine.Rendering;
public static class BuildSnowScene {
 const string Folder="Assets/Environment/SnowPlain";
 static float Height(float x,float z){float edge=Mathf.SmoothStep(0,1,Mathf.Clamp01((new Vector2(x,z).magnitude-25)/130));return -.18f+.22f*Mathf.PerlinNoise(x*.035f+70,z*.035f+60)+edge*(1.8f+6*Mathf.PerlinNoise(x*.013f+20,z*.013f+40));}
 public static string Run(){
  if(EditorApplication.isPlaying)throw new Exception("Exit play mode first");
  var scene=SceneManager.GetActiveScene();if(scene.path!="Assets/Scene/Scene1.unity")throw new Exception("Scene1 must be active");
  Directory.CreateDirectory("artifacts/backups");var backup="artifacts/backups/Scene1_before_snow_"+DateTime.Now.ToString("yyyyMMdd_HHmmss")+".unity";EditorSceneManager.SaveScene(scene,backup,true);
  Directory.CreateDirectory(Folder);AssetDatabase.Refresh();
  if(GameObject.Find("Snow Plain - Morning")!=null)throw new Exception("Snow setup already exists");
  var root=new GameObject("Snow Plain - Morning");Undo.RegisterCreatedObjectUndo(root,"Create snow plain");
  int n=512;var tex=new Texture2D(n,n,TextureFormat.RGBA32,true);var normal=new Texture2D(n,n,TextureFormat.RGBA32,true);var rand=new System.Random(41);
  for(int y=0;y<n;y++)for(int x=0;x<n;x++) {float p=Mathf.PerlinNoise(x*.035f,y*.035f),fine=(float)rand.NextDouble();float c=.86f+.10f*p+.025f*fine;tex.SetPixel(x,y,new Color(c*.98f,c*.995f,c,1));float dx=Mathf.PerlinNoise((x+1)*.035f,y*.035f)-p,dy=Mathf.PerlinNoise(x*.035f,(y+1)*.035f)-p;normal.SetPixel(x,y,new Color(.5f-dx*2,.5f-dy*2,1,1));}
  tex.Apply();normal.Apply();File.WriteAllBytes(Folder+"/SnowAlbedo.png",tex.EncodeToPNG());File.WriteAllBytes(Folder+"/SnowNormal.png",normal.EncodeToPNG());UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(normal);
  var flake=new Texture2D(64,64,TextureFormat.RGBA32,false);for(int y=0;y<64;y++)for(int x=0;x<64;x++){float d=new Vector2((x-31.5f)/31.5f,(y-31.5f)/31.5f).magnitude;flake.SetPixel(x,y,new Color(1,1,1,Mathf.Pow(Mathf.Clamp01(1-d),1.4f)));}flake.Apply();File.WriteAllBytes(Folder+"/Snowflake.png",flake.EncodeToPNG());UnityEngine.Object.DestroyImmediate(flake);AssetDatabase.Refresh();
  var ni=(TextureImporter)AssetImporter.GetAtPath(Folder+"/SnowNormal.png");ni.textureType=TextureImporterType.NormalMap;ni.SaveAndReimport();
