  var snow=new Material(Shader.Find("Standard"));snow.name="Soft packed snow";snow.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(Folder+"/SnowAlbedo.png");snow.mainTextureScale=new Vector2(70,70);snow.SetTexture("_BumpMap",AssetDatabase.LoadAssetAtPath<Texture2D>(Folder+"/SnowNormal.png"));snow.SetTextureScale("_BumpMap",new Vector2(70,70));snow.SetFloat("_BumpScale",.4f);snow.EnableKeyword("_NORMALMAP");snow.SetFloat("_Glossiness",.17f);AssetDatabase.CreateAsset(snow,Folder+"/SnowGround.mat");
  int side=161;var v=new Vector3[side*side];var uv=new Vector2[v.Length];var tris=new int[(side-1)*(side-1)*6];int k=0;for(int z=0;z<side;z++)for(int x=0;x<side;x++){int i=z*side+x;float px=(x/(float)(side-1)-.5f)*400,pz=(z/(float)(side-1)-.5f)*400;v[i]=new Vector3(px,Height(px,pz),pz);uv[i]=new Vector2(x/(float)(side-1),z/(float)(side-1));if(x<side-1&&z<side-1){tris[k++]=i;tris[k++]=i+side;tris[k++]=i+1;tris[k++]=i+1;tris[k++]=i+side;tris[k++]=i+side+1;}}
  var mesh=new Mesh();mesh.name="Snow plain 400m";mesh.vertices=v;mesh.uv=uv;mesh.triangles=tris;mesh.RecalculateNormals();mesh.RecalculateBounds();mesh.RecalculateTangents();AssetDatabase.CreateAsset(mesh,Folder+"/SnowPlain.asset");var ground=new GameObject("Snow-covered ground 400 x 400 m",typeof(MeshFilter),typeof(MeshRenderer),typeof(MeshCollider));ground.transform.SetParent(root.transform);ground.GetComponent<MeshFilter>().sharedMesh=mesh;ground.GetComponent<MeshRenderer>().sharedMaterial=snow;ground.GetComponent<MeshCollider>().sharedMesh=mesh;
  var sun=GameObject.Find("Directional Light").GetComponent<Light>();Undo.RecordObject(sun,"Morning lighting");Undo.RecordObject(sun.transform,"Morning sun angle");sun.transform.rotation=Quaternion.Euler(36,-32,0);sun.color=new Color(1,.94f,.83f);sun.intensity=1.05f;sun.shadows=LightShadows.Soft;sun.shadowStrength=.6f;RenderSettings.sun=sun;
  var sky=new Material(Shader.Find("Skybox/Procedural"));sky.name="Winter late morning sky";sky.SetFloat("_SunSize",.025f);sky.SetFloat("_AtmosphereThickness",1.15f);sky.SetColor("_SkyTint",new Color(.62f,.72f,.83f));sky.SetColor("_GroundColor",new Color(.69f,.75f,.8f));sky.SetFloat("_Exposure",1.15f);AssetDatabase.CreateAsset(sky,Folder+"/WinterMorningSky.mat");RenderSettings.skybox=sky;RenderSettings.ambientMode=AmbientMode.Trilight;RenderSettings.ambientSkyColor=new Color(.69f,.77f,.88f);RenderSettings.ambientEquatorColor=new Color(.55f,.63f,.72f);RenderSettings.ambientGroundColor=new Color(.43f,.49f,.56f);RenderSettings.fog=true;RenderSettings.fogMode=FogMode.ExponentialSquared;RenderSettings.fogDensity=.005f;RenderSettings.fogColor=new Color(.75f,.82f,.88f);RenderSettings.reflectionIntensity=.35f;
  var cam=Camera.main;Undo.RecordObject(cam.transform,"Snow plain view");Undo.RecordObject(cam,"Snow plain view");cam.transform.position=new Vector3(0,2.5f,-24);cam.transform.rotation=Quaternion.Euler(6,12,0);cam.farClipPlane=450;cam.nearClipPlane=.1f;cam.fieldOfView=65;cam.clearFlags=CameraClearFlags.Skybox;
  var pm=new Material(Shader.Find("Particles/Standard Unlit"));pm.name="Soft snowflakes";pm.mainTexture=AssetDatabase.LoadAssetAtPath<Texture2D>(Folder+"/Snowflake.png");pm.SetFloat("_Mode",2);pm.SetInt("_SrcBlend",(int)BlendMode.SrcAlpha);pm.SetInt("_DstBlend",(int)BlendMode.OneMinusSrcAlpha);pm.SetInt("_ZWrite",0);pm.EnableKeyword("_ALPHABLEND_ON");pm.renderQueue=3000;AssetDatabase.CreateAsset(pm,Folder+"/Snowflakes.mat");
  var go=new GameObject("Gentle Snowfall - follows camera");go.transform.SetParent(cam.transform,false);go.transform.position=cam.transform.position+Vector3.up*14;go.transform.rotation=Quaternion.identity;var ps=go.AddComponent<ParticleSystem>();ps.Stop(true,ParticleSystemStopBehavior.StopEmittingAndClear);var main=ps.main;main.duration=28;main.loop=true;main.prewarm=true;main.startLifetime=new ParticleSystem.MinMaxCurve(18,25);main.startSpeed=0;main.startSize=new ParticleSystem.MinMaxCurve(.035f,.09f);main.startColor=new Color(.95f,.98f,1,.8f);main.maxParticles=5000;main.simulationSpace=ParticleSystemSimulationSpace.World;main.playOnAwake=true;main.cullingMode=ParticleSystemCullingMode.AlwaysSimulate;var emission=ps.emission;emission.rateOverTime=170;var shape=ps.shape;shape.shapeType=ParticleSystemShapeType.Box;shape.scale=new Vector3(65,1,65);var velocity=ps.velocityOverLifetime;velocity.enabled=true;velocity.space=ParticleSystemSimulationSpace.World;velocity.x=.13f;velocity.y=-.8f;velocity.z=.06f;var noise=ps.noise;noise.enabled=true;noise.strength=.16f;noise.frequency=.17f;noise.scrollSpeed=.13f;var color=ps.colorOverLifetime;color.enabled=true;var gradient=new Gradient();gradient.SetKeys(new[]{new GradientColorKey(Color.white,0),new GradientColorKey(Color.white,1)},new[]{new GradientAlphaKey(0,0),new GradientAlphaKey(.8f,.12f),new GradientAlphaKey(.8f,.75f),new GradientAlphaKey(0,1)});color.color=gradient;var pr=ps.GetComponent<ParticleSystemRenderer>();pr.sharedMaterial=pm;pr.shadowCastingMode=ShadowCastingMode.Off;pr.receiveShadows=false;
  AssetDatabase.SaveAssets();EditorSceneManager.MarkSceneDirty(scene);EditorSceneManager.SaveScene(scene);SceneView.lastActiveSceneView?.LookAt(new Vector3(0,1,10),Quaternion.Euler(15,15,0),65);Selection.activeGameObject=root;return "Saved Scene1, snow ground 400m, gentle snowfall, morning lighting. Backup: "+backup;
 }
}
